def _app_root() -> pathlib.Path:
    """جذر التطبيق: بجانب الـ exe عند التجميد (frozen)، وإلا جذر المشروع."""
    if getattr(sys, "frozen", False):
        return pathlib.Path(sys.executable).resolve().parent
    return pathlib.Path(__file__).resolve().parent.parent


def _legacy_path() -> pathlib.Path:
    """مسار القاعدة القديم (للترحيل لمرة واحدة فقط)؛ تجاوز للفحص عبر SHOP_DB_LEGACY."""
    env = os.environ.get("SHOP_DB_LEGACY")
    if env:
        return pathlib.Path(env)
    return pathlib.Path(os.environ.get("LOCALAPPDATA", str(pathlib.Path.home()))) / "TechZone" / "shop.db"


def db_path() -> str:
    """data/shop.db بجانب جذر التطبيق، overridable via SHOP_DB (used by selfcheck)."""
    env = os.environ.get("SHOP_DB")
    if env:
        return env
    p = _app_root() / "data" / "shop.db"
    p.parent.mkdir(parents=True, exist_ok=True)
    return str(p)


def _migrate_once() -> None:
    """ترحيل لمرة واحدة: نسخ القاعدة القديمة إلى data/shop.db إن لم توجد الجديدة."""
    target = pathlib.Path(db_path())
    if target.exists():
        return
    legacy = _legacy_path()
    if legacy.exists() and legacy != target:
        try:
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(legacy, target)
            print(f"migrated legacy db: {legacy} -> {target}")
        except OSError:
            pass


def now() -> str:
    return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def hash_pin(pin: str, salt: bytes) -> bytes:
    return hashlib.pbkdf2_hmac("sha256", pin.encode("utf-8"), salt, 200_000)


def hash_secret(secret: str, salt: bytes) -> bytes:
    """تجزئة عبارة مرور المالك أو مفتاح الاسترداد باستخدام PBKDF2-SHA256 (200 ألف دورة)."""
    return hashlib.pbkdf2_hmac("sha256", secret.encode("utf-8"), salt, 200_000)


def sync_user_permissions_table(conn: sqlite3.Connection, user_id: int, role: str, perms_dict: dict | None = None) -> dict[str, bool]:
    """مزامنة صلاحيات المستخدم في جدول user_permissions وعمود JSON معاً."""
    normalized = parse_user_perms(role, perms_dict)
    conn.execute("DELETE FROM user_permissions WHERE user_id=?", (user_id,))
    conn.executemany(
        "INSERT INTO user_permissions(user_id, perm_key, granted) VALUES(?,?,?)",
        [(user_id, k, 1 if v else 0) for k, v in normalized.items()],
    )
    conn.execute(
        "UPDATE users SET permissions=? WHERE id=?",
        (json.dumps(normalized, ensure_ascii=False), user_id),
    )
    return normalized


_INITIALIZED_DBS = set()


class _ClosingConnection:
    """غلاف لاتصال sqlite يغلق الاتصال تلقائياً عند الخروج من with."""

    def __init__(self, conn: sqlite3.Connection):
        self._conn = conn

    def __enter__(self):
        return self._conn

    def __exit__(self, exc_type, exc, tb):
        try:
            if exc_type is None:
                self._conn.commit()
            else:
                try:
                    self._conn.rollback()
                except Exception:
                    pass
        finally:
            try:
                self._conn.close()
            except Exception:
                pass
        return False

    def __getattr__(self, name):
        return getattr(self._conn, name)


