def connect() -> "_ClosingConnection":
    _migrate_once()
    path = db_path()
    conn = sqlite3.connect(path, timeout=15, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys=ON")
    conn.execute("PRAGMA synchronous=NORMAL")
    conn.execute("PRAGMA temp_store=MEMORY")
    conn.execute("PRAGMA cache_size=-16000")
    if path not in _INITIALIZED_DBS:
        conn.execute("PRAGMA journal_mode=WAL")
        init_db(conn)
        _ensure_schema_columns(conn)
        _migrate_customers(conn)
        for idx_sql in _PERFORMANCE_INDEXES:
            conn.execute(idx_sql)
        _migrate_customer_ledger(conn)
        conn.commit()
        _INITIALIZED_DBS.add(path)
    return _ClosingConnection(conn)



def images_dir(subdir: str | None = None) -> pathlib.Path:
    """مجلد حفظ الصور المضغوطة على القرص (data/images/...)."""
    base = pathlib.Path(db_path()).parent / "images"
    target = (base / subdir) if subdir else base
    target.mkdir(parents=True, exist_ok=True)
    return target


def save_image_to_disk(data_url: str, subdir: str, filename_stem: str) -> str:
    """تحويل data:image/... إلى ملف WebP مضغوط على القرص وإرجاع المسار النسبي."""
    if not isinstance(data_url, str):
        raise ValueError("Invalid image data")
    s = data_url.strip()
    if not s.startswith("data:image/") or "," not in s:
        return s
    import base64
    import io
    header, b64_part = s.split(",", 1)
    raw = base64.b64decode(b64_part)
    out_dir = images_dir(subdir)
    out_file = out_dir / f"{filename_stem}.webp"
    try:
        from PIL import Image
        with Image.open(io.BytesIO(raw)) as im:
            if im.mode in ("RGBA", "LA") or (im.mode == "P" and "transparency" in im.info):
                im = im.convert("RGBA")
            else:
                im = im.convert("RGB")
            im.thumbnail((800, 800))
            im.save(out_file, format="WEBP", quality=82, method=4)
        return f"{subdir}/{filename_stem}.webp"
    except Exception:
        ext = "png"
        hl = header.lower()
        if "jpeg" in hl or "jpg" in hl:
            ext = "jpg"
        elif "webp" in hl:
            ext = "webp"
        elif "gif" in hl:
            ext = "gif"
        fallback_file = out_dir / f"{filename_stem}.{ext}"
        fallback_file.write_bytes(raw)
        return f"{subdir}/{filename_stem}.{ext}"


def _migrate_base64_images_to_disk(conn) -> int:
    """ترحيل صور المنتجات المخزنة كـ Base64 في SQLite إلى ملفات WebP على القرص في data/images/products/."""
    migrated = 0
    try:
        rows = conn.execute(
            "SELECT id, image FROM products WHERE image LIKE 'data:image/%'"
        ).fetchall()
        for r in rows:
            pid = r["id"]
            try:
                rel_path = save_image_to_disk(r["image"], "products", f"prod_{pid}")
                if rel_path and not rel_path.startswith("data:image/"):
                    conn.execute("UPDATE products SET image=? WHERE id=?", (rel_path, pid))
                    migrated += 1
            except Exception:
                pass
        if migrated > 0:
            conn.commit()
    except Exception:
        pass
    return migrated

def backup_database(reason: str = "manual") -> pathlib.Path | None:
    """نسخ احتياطي فوري لقاعدة البيانات عبر sqlite3 online backup API مع تدوير النسخ القديمة."""
    src_path = pathlib.Path(db_path())
    if not src_path.exists():
        return None
    backups_dir = src_path.parent / "backups"
    backups_dir.mkdir(parents=True, exist_ok=True)
    ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    safe_reason = re.sub(r"[^a-zA-Z0-9_\-]", "", reason) or "auto"
    dest_path = backups_dir / f"shop_{ts}_{safe_reason}.db"

    try:
        src_conn = sqlite3.connect(str(src_path), timeout=10)
        dest_conn = sqlite3.connect(str(dest_path))
        try:
            src_conn.backup(dest_conn)
        finally:
            dest_conn.close()
            src_conn.close()
        _rotate_backups(backups_dir, max_keep=30)
        return dest_path
    except Exception as e:
        print(f"Database backup error: {e}", file=sys.stderr)
        return None


def _rotate_backups(backups_dir: pathlib.Path, max_keep: int = 30) -> None:
    """الاحتفاظ بآخر max_keep نسخة احتياطية وحذف النسخ الأقدم."""
    try:
        backups = sorted(
            backups_dir.glob("shop_*.db"),
            key=lambda p: p.stat().st_mtime,
            reverse=True,
        )
        for old in backups[max_keep:]:
            try:
                old.unlink()
            except OSError:
                pass
    except Exception:
        pass


def list_backups() -> list[dict]:
    """استعراض قائمة النسخ الاحتياطية المتوفرة."""
    src_path = pathlib.Path(db_path())
    backups_dir = src_path.parent / "backups"
    if not backups_dir.exists():
        return []
    items = []
    for p in sorted(backups_dir.glob("shop_*.db"), key=lambda x: x.stat().st_mtime, reverse=True):
        stat = p.stat()
        items.append({
            "name": p.name,
            "path": str(p),
            "size_bytes": stat.st_size,
            "size_kb": round(stat.st_size / 1024, 1),
            "created_at": datetime.datetime.fromtimestamp(stat.st_mtime).strftime("%Y-%m-%d %H:%M:%S"),
        })
    return items


def daily_startup_backup() -> pathlib.Path | None:
    """نسخ احتياطي تلقائي عند أول تشغيل يومياً."""
    src_path = pathlib.Path(db_path())
    if not src_path.exists():
        return None
    backups_dir = src_path.parent / "backups"
    today_prefix = f"shop_{datetime.datetime.now().strftime('%Y%m%d')}"
    if backups_dir.exists():
        for b in backups_dir.glob(f"{today_prefix}_*.db"):
            return b  # تم أخذ نسخة اليوم بالفعل
    return backup_database("startup")


def restore_database(backup_name: str) -> dict:
    """استرجاع قاعدة البيانات من نسخة احتياطية محددة مع أخذ نسخة أمان فورية مسبقة."""
    src_path = pathlib.Path(db_path())
    backups_dir = src_path.parent / "backups"

    clean_name = pathlib.Path(backup_name).name
    backup_file = backups_dir / clean_name

    if not backup_file.exists() or not backup_file.is_file():
        raise ValueError("ملف النسخة الاحتياطية غير موجود")

    # 1. فحص سلامة وتماسك النسخة الاحتياطية
    try:
        chk_conn = sqlite3.connect(str(backup_file), timeout=5)
        res = chk_conn.execute("PRAGMA quick_check").fetchone()
        chk_conn.close()
        if not res or res[0] != "ok":
            raise ValueError("ملف النسخة الاحتياطية تالف أو غير متماسك")
    except Exception as e:
        raise ValueError(f"فشل فحص سلامة النسخة الاحتياطية: {e}")

    # 2. أخذ نسخة أمان تلقائية فورية من الحالة الحالية قبل الاسترجاع
    safety_snap = backup_database(reason="before_restore")

    # 3. استخدام sqlite3 online backup API لنسخ الصفحات إلى الملف الحي
    bck_conn = sqlite3.connect(str(backup_file), timeout=10)
    dest_conn = sqlite3.connect(str(src_path), timeout=15)
    try:
        bck_conn.backup(dest_conn)
        dest_conn.commit()
    finally:
        dest_conn.close()
        bck_conn.close()

    return {
        "restored_from": clean_name,
        "safety_backup": safety_snap.name if safety_snap else None,
    }


