def _migrate_customers(conn):
    """ترحيل العملاء من جدول المبيعات إلى جدول العملاء المنفصل."""
    try:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, phone TEXT, created_at TEXT NOT NULL, UNIQUE(name, phone))"
        )
        t = now()
        customers = conn.execute(
            "SELECT DISTINCT TRIM(customer_name) AS cname, NULLIF(TRIM(customer_phone), '') AS cphone "
            "FROM sales WHERE customer_name IS NOT NULL AND TRIM(customer_name) != ''"
        ).fetchall()
        for c in customers:
            cname, cphone = c["cname"], c["cphone"]
            existing = conn.execute(
                "SELECT id FROM customers WHERE name=? AND COALESCE(phone,'')=COALESCE(?, '')",
                (cname, cphone),
            ).fetchone()
            if not existing:
                conn.execute(
                    "INSERT OR IGNORE INTO customers(name, phone, created_at) VALUES(?,?,?)",
                    (cname, cphone, t),
                )
        conn.execute(
            """UPDATE sales SET customer_id = (
               SELECT id FROM customers
               WHERE customers.name = TRIM(sales.customer_name)
                 AND COALESCE(customers.phone, '') = COALESCE(NULLIF(TRIM(sales.customer_phone), ''), '')
               LIMIT 1
            ) WHERE customer_id IS NULL AND customer_name IS NOT NULL AND TRIM(customer_name) != ''"""
        )
        conn.commit()
    except Exception as e:
        print(f"Migration error: {e}")


def _migrate_customer_ledger(conn: sqlite3.Connection) -> None:
    """ترحيل لمرة واحدة: تعبئة دفتر الأستاذ (customer_ledger) وأرصدة العملاء المخزّنة للبيانات التاريخية."""
    try:
        flag = conn.execute("SELECT value FROM settings WHERE key='customer_ledger_migrated'").fetchone()
        if flag and flag["value"] == "1":
            return

        # 1) تحديث الأرصدة المجمّعة في جدول customers عبر SQL سريع
        conn.execute(
            """
            WITH sale_credit AS (
                SELECT sale_id, COALESCE(SUM(amount), 0) AS credit_amt
                FROM payments WHERE method = 'credit' GROUP BY sale_id
            ),
            sale_ret AS (
                SELECT sale_id, COALESCE(SUM(total), 0) AS ret_amt
                FROM sale_returns GROUP BY sale_id
            ),
            cust_sales_links AS (
                SELECT customer_id AS cid, id AS sid FROM sales WHERE customer_id IS NOT NULL
                UNION
                SELECT c.id AS cid, s.id AS sid FROM customers c JOIN sales s ON s.customer_id IS NULL AND s.customer_name = c.name
                UNION
                SELECT c.id AS cid, s.id AS sid FROM customers c JOIN sales s ON c.phone IS NOT NULL AND c.phone != '' AND s.customer_phone = c.phone
            ),
            cust_sales_agg AS (
                SELECT l.cid,
                       COALESCE(SUM(MAX(0, s.total - COALESCE(sr.ret_amt, 0))), 0) AS total_purchases,
                       COALESCE(SUM(MAX(0, COALESCE(sc.credit_amt, 0) - COALESCE(sr.ret_amt, 0))), 0) AS credit_total
                FROM cust_sales_links l
                JOIN sales s ON s.id = l.sid
                LEFT JOIN sale_credit sc ON sc.sale_id = s.id
                LEFT JOIN sale_ret sr ON sr.sale_id = s.id
                GROUP BY l.cid
            ),
            cust_paid AS (
                SELECT customer_id AS cid, COALESCE(SUM(amount), 0) AS paid_total
                FROM customer_payments GROUP BY customer_id
            ),
            cust_inst_charge AS (
                SELECT customer_id AS cid,
                       COALESCE(SUM(CASE WHEN sale_id IS NULL THEN principal ELSE 0 END), 0) AS standalone_principal,
                       COALESCE(SUM(ledger_charge), 0) AS ledger_charge
                FROM installment_plans
                WHERE status != 'cancelled'
                GROUP BY customer_id
            ),
            cust_inst_paid AS (
                SELECT ip.customer_id AS cid, COALESCE(SUM(ip.amount), 0) AS paid_total
                FROM installment_payments ip
                JOIN installment_plans p ON p.id = ip.plan_id
                WHERE p.status != 'cancelled'
                GROUP BY ip.customer_id
            )
            UPDATE customers
            SET total_purchases = COALESCE((SELECT total_purchases FROM cust_sales_agg WHERE cid = customers.id), 0)
                              + COALESCE((SELECT standalone_principal FROM cust_inst_charge WHERE cid = customers.id), 0),
                credit_total = COALESCE((SELECT credit_total FROM cust_sales_agg WHERE cid = customers.id), 0)
                             + COALESCE((SELECT ledger_charge FROM cust_inst_charge WHERE cid = customers.id), 0),
                paid_total = COALESCE((SELECT paid_total FROM cust_paid WHERE cid = customers.id), 0)
                           + COALESCE((SELECT paid_total FROM cust_inst_paid WHERE cid = customers.id), 0),
                debt = MAX(0, (COALESCE((SELECT credit_total FROM cust_sales_agg WHERE cid = customers.id), 0)
                             + COALESCE((SELECT ledger_charge FROM cust_inst_charge WHERE cid = customers.id), 0))
                            - (COALESCE((SELECT paid_total FROM cust_paid WHERE cid = customers.id), 0)
                             + COALESCE((SELECT paid_total FROM cust_inst_paid WHERE cid = customers.id), 0)))
            """
        )

        # 2) تعبئة حركات دفتر الأستاذ التاريخية فقط إذا كان الجدول فارغاً
        has_rows = conn.execute("SELECT 1 FROM customer_ledger LIMIT 1").fetchone()
        if not has_rows:
            credit_rows = conn.execute(
                """
                WITH sale_credit AS (
                    SELECT sale_id, COALESCE(SUM(amount), 0) AS credit_amt
                    FROM payments WHERE method = 'credit' GROUP BY sale_id
                ),
                sale_ret AS (
                    SELECT sale_id, COALESCE(SUM(total), 0) AS ret_amt
                    FROM sale_returns GROUP BY sale_id
                ),
                cust_sales_links AS (
                    SELECT customer_id AS cid, id AS sid FROM sales WHERE customer_id IS NOT NULL
                    UNION
                    SELECT c.id AS cid, s.id AS sid FROM customers c JOIN sales s ON s.customer_id IS NULL AND s.customer_name = c.name
                    UNION
                    SELECT c.id AS cid, s.id AS sid FROM customers c JOIN sales s ON c.phone IS NOT NULL AND c.phone != '' AND s.customer_phone = c.phone
                )
                SELECT l.cid AS customer_id, s.id AS sale_id, s.invoice_no AS ref, s.created_at,
                       MAX(0, COALESCE(sc.credit_amt, 0) - COALESCE(sr.ret_amt, 0)) AS net_credit,
                       s.user_id
                FROM cust_sales_links l
                JOIN sales s ON s.id = l.sid
                LEFT JOIN sale_credit sc ON sc.sale_id = s.id
                LEFT JOIN sale_ret sr ON sr.sale_id = s.id
                WHERE MAX(0, COALESCE(sc.credit_amt, 0) - COALESCE(sr.ret_amt, 0)) > 0
                """
            ).fetchall()

            voucher_rows = conn.execute(
                """SELECT cp.id AS voucher_id, cp.customer_id, cp.sale_id, cp.ref, cp.created_at,
                          cp.amount, cp.method, cp.ref_no, cp.notes, cp.user_id, u.name AS user_name
                   FROM customer_payments cp
                   LEFT JOIN users u ON u.id = cp.user_id"""
            ).fetchall()

            inst_charge_rows = conn.execute(
                """SELECT p.id AS plan_id, p.customer_id, p.sale_id, p.plan_no AS ref, p.created_at,
                          p.ledger_charge, p.title, p.user_id, u.name AS user_name
                   FROM installment_plans p
                   LEFT JOIN users u ON u.id = p.user_id
                   WHERE p.status != 'cancelled' AND p.ledger_charge > 0"""
            ).fetchall()

            inst_pay_rows = conn.execute(
                """SELECT ip.id AS ipay_id, ip.customer_id, ip.plan_id, ip.receipt_no AS ref, ip.created_at,
                          ip.amount, ip.method, ip.ref_no, ip.notes, ip.user_id, u.name AS user_name
                   FROM installment_payments ip
                   JOIN installment_plans p ON p.id = ip.plan_id
                   LEFT JOIN users u ON u.id = ip.user_id
                   WHERE p.status != 'cancelled'"""
            ).fetchall()

            by_cust = {}
            for r in credit_rows:
                by_cust.setdefault(r["customer_id"], []).append((
                    r["created_at"], 0, r["sale_id"],
                    (r["customer_id"], r["created_at"], "credit_sale", r["ref"], r["sale_id"], None, None,
                     r["net_credit"], 0, "credit", None, f"فاتورة آجلة ({r['ref']})", r["user_id"], None)
                ))
            for ic in inst_charge_rows:
                by_cust.setdefault(ic["customer_id"], []).append((
                    ic["created_at"], 0, ic["plan_id"],
                    (ic["customer_id"], ic["created_at"], "installment_charge", ic["ref"], ic["sale_id"], None, ic["plan_id"],
                     ic["ledger_charge"], 0, "credit", None, f"خطة أقساط ({ic['ref']} - {ic['title']})", ic["user_id"], ic["user_name"])
                ))
            for v in voucher_rows:
                note = v["notes"] or ("سداد نقدي" if v["method"] == "cash" else "سداد محفظة")
                by_cust.setdefault(v["customer_id"], []).append((
                    v["created_at"], 1, v["voucher_id"],
                    (v["customer_id"], v["created_at"], "voucher", v["ref"], v["sale_id"], v["voucher_id"], None,
                     0, v["amount"], v["method"], v["ref_no"], note, v["user_id"], v["user_name"])
                ))
            for ip in inst_pay_rows:
                note = ip["notes"] or f"تحصيل قسط ({ip['ref']})"
                by_cust.setdefault(ip["customer_id"], []).append((
                    ip["created_at"], 1, ip["ipay_id"],
                    (ip["customer_id"], ip["created_at"], "installment_payment", ip["ref"], None, None, ip["plan_id"],
                     0, ip["amount"], ip["method"], ip["ref_no"], note, ip["user_id"], ip["user_name"])
                ))

            to_insert = []
            for cid, evs in by_cust.items():
                evs.sort(key=lambda x: (x[0], x[1], x[2]))
                running = 0
                for _, _, _, tpl in evs:
                    running = max(0, running + tpl[7] - tpl[8])
                    to_insert.append(tpl[:9] + (running,) + tpl[9:])

            if to_insert:
                conn.executemany(
                    """INSERT INTO customer_ledger
                       (customer_id, created_at, kind, ref, sale_id, voucher_id, plan_id, debit, credit, balance_after, method, ref_no, notes, user_id, user_name)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    to_insert,
                )

        conn.execute("INSERT OR REPLACE INTO settings(key, value) VALUES('customer_ledger_migrated', '1')")
        conn.commit()
    except Exception as e:
        print(f"Ledger migration error: {e}")


