def _migrate_strict_permissions_v2(conn: sqlite3.Connection) -> None:
    """ترحيل لمرة واحدة: إعادة ضبط غير المديرين على كاشير صارم ومزامنة user_permissions والأقسام."""
    row = conn.execute("SELECT value FROM settings WHERE key='migration_v2_strict_perms'").fetchone()
    if row and row["value"] == "1":
        return

    # 1) تحديث perm_keys في جدول modules للنسخ المبنية في النظام وترحيل الاستنساخات القديمة
    builtin_perms = {row_m[0]: row_m[5] for row_m in DEFAULT_MODULES}
    for m_row in conn.execute("SELECT key, is_builtin, perm_keys FROM modules").fetchall():
        mkey = m_row["key"]
        if m_row["is_builtin"] and mkey in builtin_perms:
            conn.execute(
                "UPDATE modules SET perm_keys=?, updated_at=? WHERE key=?",
                (json.dumps(builtin_perms[mkey], ensure_ascii=False), now(), mkey),
            )
        else:
            try:
                old_list = json.loads(m_row["perm_keys"] or "[]")
            except Exception:
                old_list = []
            new_list = []
            for pk in old_list:
                if pk in _LEGACY_PERM_MAP:
                    new_list.extend(_LEGACY_PERM_MAP[pk])
                elif pk in ALL_PERM_KEYS:
                    new_list.append(pk)
            dedup = list(dict.fromkeys(new_list))
            conn.execute(
                "UPDATE modules SET perm_keys=?, updated_at=? WHERE key=?",
                (json.dumps(dedup, ensure_ascii=False), now(), mkey),
            )

    # 2) ترحيل المستخدمين: إعادة ضبط كل الحسابات غير الإدارية تلقائياً على كاشير صارم ومزامنة user_permissions
    t = now()
    for u_row in conn.execute("SELECT id, username, role FROM users").fetchall():
        if u_row["role"] == "admin":
            sync_user_permissions_table(conn, u_row["id"], "admin", ALL_ADMIN_PERMS)
            conn.execute("UPDATE users SET job_preset='admin' WHERE id=?", (u_row["id"],))
        else:
            sync_user_permissions_table(conn, u_row["id"], "cashier", STRICT_CASHIER_PERMS)
            conn.execute("UPDATE users SET job_preset='cashier_strict' WHERE id=?", (u_row["id"],))
            conn.execute(
                """INSERT INTO perm_audit_log(ts, actor_id, actor_name, target_user_id, target_username, action, diff_json)
                   VALUES(?, NULL, 'النظام (ترحيل أمني)', ?, ?, 'migration_strict_reset', ?)""",
                (
                    t,
                    u_row["id"],
                    u_row["username"],
                    json.dumps({"preset": "cashier_strict", "granted": sorted(k for k, v in STRICT_CASHIER_PERMS.items() if v)}, ensure_ascii=False),
                ),
            )

    conn.execute(
        "INSERT INTO settings(key, value) VALUES('migration_v2_strict_perms', '1') "
        "ON CONFLICT(key) DO UPDATE SET value=excluded.value"
    )


