def _migrate_erp_cost_snapshot(conn: sqlite3.Connection) -> None:
    """تحديث لمرة واحدة: ضمان تثبيت cost_unit في الفواتير وقطع الغيار التاريخية وترقية قوالب الصلاحيات."""
    flag = conn.execute("SELECT value FROM settings WHERE key='erp_cost_snapshot_migrated'").fetchone()
    if flag and flag["value"] == "1":
        return
    conn.execute(
        "UPDATE sale_items SET cost_unit = COALESCE((SELECT p.cost FROM products p WHERE p.id = sale_items.product_id), 0) WHERE cost_unit = 0"
    )
    conn.execute(
        "UPDATE repair_parts SET cost_unit = COALESCE((SELECT p.cost FROM products p WHERE p.id = repair_parts.product_id), unit_price, 0) WHERE cost_unit = 0"
    )
    # تحديث قوالب الوظائف المدمجة لتشمل الصلاحيات الـ 63
    t = now()
    for p in DEFAULT_ROLE_PRESETS:
        conn.execute(
            """INSERT INTO permission_roles(key, name, description, badge_color, perms_json, is_builtin, created_at)
               VALUES(?,?,?,?,?,1,?)
               ON CONFLICT(key) DO UPDATE SET
                 description=excluded.description,
                 perms_json=excluded.perms_json""",
            (
                p["key"],
                p["name"],
                p.get("description", ""),
                p.get("badge_color", "slate"),
                json.dumps(p["perms"], ensure_ascii=False),
                t,
            ),
        )
    conn.execute(
        "INSERT INTO settings(key, value) VALUES('erp_cost_snapshot_migrated', '1') "
        "ON CONFLICT(key) DO UPDATE SET value=excluded.value"
    )


def seed_modules_if_empty(conn: sqlite3.Connection) -> None:
    """زرع الأقسام الافتراضية الـ 15 عند خلو جدول modules أو إضافة الأقسام الجديدة بأمان."""
    t = now()
    cnt = conn.execute("SELECT COUNT(*) c FROM modules").fetchone()["c"]
    if cnt == 0:
        rows = [
            (key, title, icon, color, url, "", json.dumps(perms, ensure_ascii=False), order, 1, is_core, 1, None, t, t)
            for key, title, icon, color, url, perms, order, is_core in DEFAULT_MODULES
        ]
        conn.executemany(
            """INSERT INTO modules
               (key, title, icon, color, url, params, perm_keys, sort_order, enabled, is_core, is_builtin, clone_of, created_at, updated_at)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            rows,
        )
        return
    existing = {r["key"] for r in conn.execute("SELECT key FROM modules").fetchall()}
    for key, title, icon, color, url, perms, order, is_core in DEFAULT_MODULES:
        if key not in existing:
            conn.execute(
                """INSERT OR IGNORE INTO modules
                   (key, title, icon, color, url, params, perm_keys, sort_order, enabled, is_core, is_builtin, clone_of, created_at, updated_at)
                   VALUES(?,?,?,?,?,?,?,?,1,?,1,NULL,?,?)""",
                (key, title, icon, color, url, "", json.dumps(perms, ensure_ascii=False), order, is_core, t, t),
            )


def seed_profiles_if_empty(conn: sqlite3.Connection) -> None:
    """زرع قوالب النشاط الافتراضية في business_profiles ووسم بيانات البداية التجريبية."""
    from profiles import DEFAULT_BUSINESS_PROFILES, DEFAULT_RETAIL_CATS, DEFAULT_RETAIL_SKUS

    if DEFAULT_RETAIL_SKUS:
        ph = ",".join("?" for _ in DEFAULT_RETAIL_SKUS)
        conn.execute(
            f"UPDATE products SET demo_profile='retail_electronics' WHERE demo_profile IS NULL AND sku IN ({ph})",
            DEFAULT_RETAIL_SKUS,
        )
    if DEFAULT_RETAIL_CATS:
        ph_c = ",".join("?" for _ in DEFAULT_RETAIL_CATS)
        conn.execute(
            f"UPDATE categories SET demo_profile='retail_electronics' WHERE demo_profile IS NULL AND name IN ({ph_c})",
            DEFAULT_RETAIL_CATS,
        )
    existing_profs = {r["key"] for r in conn.execute("SELECT key FROM business_profiles").fetchall()}
    if len(existing_profs) >= len(DEFAULT_BUSINESS_PROFILES):
        return
    t = now()
    rows = [
        (
            k,
            v["label"],
            v.get("description", ""),
            json.dumps(v.get("modules_enabled", []), ensure_ascii=False),
            json.dumps(v.get("module_titles", {}), ensure_ascii=False),
            json.dumps(v.get("labels", {}), ensure_ascii=False),
            json.dumps(v.get("demo_catalog", []), ensure_ascii=False),
            v.get("default_start_page", "pos"),
            int(v.get("sort_order", 10)),
            1,
            t,
            t,
        )
        for k, v in DEFAULT_BUSINESS_PROFILES.items()
    ]
    conn.executemany(
        """INSERT OR IGNORE INTO business_profiles
           (key, label, description, modules_enabled, module_titles, labels, demo_catalog, default_start_page, sort_order, is_builtin, created_at, updated_at)
           VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
        rows,
    )


def init_db(conn: sqlite3.Connection) -> None:
    conn.executescript(SCHEMA)
    _seed(conn)
    conn.commit()


def _seed(conn: sqlite3.Connection) -> None:
    """Seed first-run only (settings + users + demo catalog)."""
    if conn.execute("SELECT COUNT(*) c FROM settings").fetchone()["c"]:
        return
    t = now()
    defaults = {
        "store_name": "تك زون للإلكترونيات",
        "store_address": "شارع جامعة الدول العربية، الجيزة، مصر",
        "store_phone": "01000000000",
        "currency": "ج.م",
        "tax_enabled": "1",
        "tax_rate": "14",
        "pos_card_size": "200",
        "login_mode": "pin_only",
        "default_start_page": "pos",
        "default_start_mode": "window",
        "os_default_theme": "dark",
        "whatsapp_send_enabled": "1",
        "pos_print_preview": "1",
        "print_show_dialog": "0",
        "print_printer_name": "",
        "close_exit_app": "0",
        "login_max_attempts": "5",
        "login_lockout_minutes": "10",
        "migration_v2_strict_perms": "1",
    }
    conn.executemany("INSERT INTO settings(key, value) VALUES(?, ?)", list(defaults.items()))

    for username, name, role, pin in (("admin", "المدير", "admin", "1234"), ("cashier", "أحمد محمد", "cashier", "1111")):
        salt = os.urandom(16)
        preset = "admin" if role == "admin" else "cashier_strict"
        perms_dict = ALL_ADMIN_PERMS if role == "admin" else DEFAULT_CASHIER_PERMS
        perms_json = json.dumps(perms_dict, ensure_ascii=False)
        cur = conn.execute(
            "INSERT INTO users(username, name, role, pin_salt, pin_hash, permissions, is_active, job_preset, created_at) VALUES(?,?,?,?,?,?,?,?,?)",
            (username, name, role, salt, hash_pin(pin, salt), perms_json, 1, preset, t),
        )
        sync_user_permissions_table(conn, cur.lastrowid, role, perms_dict)

    cats = ["أجهزة كمبيوتر", "لابتوبات", "إكسسوارات", "شبكات", "كاميرات", "صيانة", "أجهزة لوحية", "صوتيات", "تخزين"]
    for c in cats:
        conn.execute("INSERT INTO categories(name) VALUES(?)", (c,))
    cat_id = {r["name"]: r["id"] for r in conn.execute("SELECT id, name FROM categories")}

    # sku, name, category, price, cost, qty, min_qty, tracked
    products = [
        ("MBP-M2-16", "ماك بوك برو M2، ذاكرة 16 جيجا، 512 SSD", "لابتوبات", 549900, 480000, 18, 5, 0),
        ("LGM-MX3S", "ماوس لوجيتك لاسلكي MX Master 3S", "إكسسوارات", 45000, 30000, 25, 5, 0),
        ("KB-RGB-002", "كيبورد ميكانيكي RGB للألعاب", "إكسسوارات", 29900, 18000, 12, 5, 0),
        ("TP-SWITCH-8", "سويتش شبكة تي بي لينك 8 منافذ", "شبكات", 12000, 8000, 30, 5, 0),
        ("CAM-WIFI-01", "كاميرا مراقبة خارجية واي فاي", "كاميرات", 35000, 22000, 15, 5, 0),
        ("DL-OPTI-P4", "جهاز مكتبي ديل أوبتيبليكس", "أجهزة كمبيوتر", 210000, 160000, 3, 2, 1),
        ("CPU-I7-12", "معالج إنتل كور i7 الجيل 12", "صيانة", 165000, 130000, 10, 3, 0),
        ("GPU-3060TI", "كرت شاشة RTX 3060 Ti", "صيانة", 189900, 150000, 6, 2, 0),
        ("DX-15-2023", "Dell XPS 15 لابتوب (i7, 16GB, 512GB)", "لابتوبات", 549900, 480000, 2, 5, 0),
        ("SM-SSD-T7", "Samsung T7 SSD 1TB", "تخزين", 42000, 30000, 1, 5, 0),
        ("SN-HP-XM4", "سماعات سوني WH-1000XM4", "صوتيات", 119900, 90000, 24, 5, 0),
        ("CH-25W-USBC", "شاحن 25W USB-C", "إكسسوارات", 5000, 2500, 40, 5, 0),
        ("BAT-14-LT", "بطارية لابتوب 14 إنش", "صيانة", 25000, 15000, 8, 3, 0),
        ("SCR-14-LT", "شاشة لابتوب 14 بوصة", "صيانة", 45000, 30000, 5, 3, 0),
    ]
    for sku, name, cat, price, cost, qty, min_qty, tracked in products:
        cur = conn.execute(
            "INSERT INTO products(sku, name, category_id, price, cost, qty, min_qty, tracked, created_at) VALUES(?,?,?,?,?,?,?,?,?)",
            (sku, name, cat_id[cat], price, cost, qty, min_qty, tracked, t),
        )
        if tracked:
            for i in range(qty):
                conn.execute(
                    "INSERT INTO serials(product_id, serial, status, created_at) VALUES(?,?,?,?)",
                    (cur.lastrowid, f"DL-{88231 + i}", "in_stock", t),
                )
    conn.commit()
